import type { BankQuestion } from "@/lib/bank";

/** State Government and Local Government (Indian Polity): 222 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "polity-state-local-govt-1", "question": "The Governor of a State is appointed by the:", "options": ["Chief Justice of the High Court", "Chief Minister", "State Legislative Assembly", "President"], "answer": 3, "explanation": "Article 155 says the President appoints the Governor by warrant under his hand and seal. Governors are not elected.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-state-local-govt-2", "question": "The 73rd Constitutional Amendment Act, 1992 deals with:", "options": ["Municipalities", "Cooperative societies", "Panchayati Raj institutions", "Anti-defection"], "answer": 2, "explanation": "The 73rd Amendment added Part IX and the Eleventh Schedule on panchayats. Municipalities came with the 74th Amendment.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-state-local-govt-3", "question": "What is the minimum age to be appointed Governor?", "options": ["25 years", "21 years", "30 years", "35 years"], "answer": 3, "explanation": "Article 157 requires the Governor to be an Indian citizen who has completed 35 years of age.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-4", "question": "The normal term of a panchayat is:", "options": ["Three years", "Six years", "Five years", "Four years"], "answer": 2, "explanation": "Article 243E gives every panchayat a five-year term from its first meeting, unless it is dissolved earlier.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-state-local-govt-5", "question": "Provisions on Municipalities are in which Part of the Constitution?", "options": ["Part X", "Part IX-A", "Part IX", "Part VIII"], "answer": 1, "explanation": "The 74th Amendment (1992) added Part IX-A (Articles 243P–243ZG) on municipalities. Part IX covers panchayats, and Part VIII covers Union Territories.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-6", "question": "How many subjects does the Eleventh Schedule list for panchayats?", "options": ["47", "29", "18", "22"], "answer": 1, "explanation": "The Eleventh Schedule lists 29 subjects for panchayats. The Twelfth Schedule lists 18 for municipalities.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-state-local-govt-7", "question": "The Twelfth Schedule, listing the functions of municipalities, has how many items?", "options": ["25", "18", "29", "12"], "answer": 1, "explanation": "The Twelfth Schedule, added by the 74th Amendment, lists 18 items such as urban planning and water supply. 29 is the Eleventh Schedule count.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-8", "question": "Under Article 243D, the share of panchayat seats reserved for women must be at least:", "options": ["One-third", "Two-thirds", "One-half", "One-fourth"], "answer": 0, "explanation": "The Constitution requires at least one-third of seats, and one-third of chairperson posts, to be reserved for women. Many States have raised this to 50% by their own laws.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-state-local-govt-9", "question": "Elections to panchayats are conducted by the:", "options": ["State Election Commission", "District Collector", "Election Commission of India", "State Government"], "answer": 0, "explanation": "Article 243K puts panchayat elections under a State Election Commission appointed by the Governor. Article 243ZA does the same for municipalities.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-state-local-govt-10", "question": "A State Finance Commission to review the finances of panchayats is set up every five years by the:", "options": ["State Legislative Assembly", "President", "Governor", "Finance Commission of India"], "answer": 2, "explanation": "Under Article 243I the Governor sets up a State Finance Commission every five years. Article 243Y extends its role to municipalities. The Union Finance Commission is under Article 280.", "difficulty": "moderate", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-11", "question": "A State Legislative Council can be created or abolished by:", "options": ["The Governor, on the Chief Minister's advice", "The President by order", "Parliament by law, after a resolution of the State Assembly", "The State Legislative Assembly alone"], "answer": 2, "explanation": "Under Article 169 Parliament creates or abolishes a Council by law, after the Assembly passes a resolution by a special majority. Such a law is not treated as an amendment under Article 368.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-state-local-govt-12", "question": "Under Article 164, the Chief Minister is appointed by the:", "options": ["Chief Justice of the High Court", "President", "Speaker of the Assembly", "Governor"], "answer": 3, "explanation": "Article 164(1) says the Governor appoints the Chief Minister, and the other ministers on the Chief Minister's advice.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-state-local-govt-13", "question": "Which was the first State to introduce Panchayati Raj, at Nagaur on 2 October 1959?", "options": ["Rajasthan", "Maharashtra", "Gujarat", "Andhra Pradesh"], "answer": 0, "explanation": "Rajasthan was first, at Nagaur, following the Balwant Rai Mehta Committee (1957). Andhra Pradesh followed later in 1959.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-state-local-govt-14", "question": "Which committee recommended a two-tier Panchayati Raj system?", "options": ["Balwant Rai Mehta Committee", "G. V. K. Rao Committee", "Ashok Mehta Committee", "L. M. Singhvi Committee"], "answer": 2, "explanation": "The Ashok Mehta Committee (1977–78) proposed two tiers: Zila Parishad and Mandal Panchayat. Balwant Rai Mehta (1957) had recommended three tiers.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-15", "question": "Under Article 243(b), the Gram Sabha consists of:", "options": ["All elected panchayat members", "All adult residents, whether registered or not", "Everyone on the electoral rolls of the village within the panchayat area", "The Sarpanch and ward members"], "answer": 2, "explanation": "The Gram Sabha is the body of everyone registered in the electoral rolls of a village in the panchayat area. Article 243A lets the State legislature give it powers.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-16", "question": "Part IX (Panchayats) does NOT apply to which group of States?", "options": ["Assam, Tripura and Sikkim", "Manipur, Arunachal Pradesh and Goa", "Nagaland, Meghalaya and Mizoram", "Kerala, Goa and Sikkim"], "answer": 2, "explanation": "Article 243M exempts Nagaland, Meghalaya and Mizoram. It also exempts Scheduled and tribal areas, the hill areas of Manipur that have District Councils, and parts of Darjeeling.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-17", "question": "The Panchayats (Extension to the Scheduled Areas) Act, 1996 extends Part IX to:", "options": ["Union Territories", "Fifth Schedule Scheduled Areas", "Sixth Schedule tribal areas", "Cantonment areas"], "answer": 1, "explanation": "PESA extends the panchayat provisions to Fifth Schedule areas, with changes that give Gram Sabhas strong powers over local resources. It was based on the Bhuria Committee's recommendations.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-18", "question": "The Sixth Schedule covers tribal areas in all of these States EXCEPT:", "options": ["Tripura", "Assam", "Meghalaya", "Manipur"], "answer": 3, "explanation": "The Sixth Schedule applies to tribal areas of Assam, Meghalaya, Tripura and Mizoram. Manipur's hill district councils are set up under a State law, not the Sixth Schedule.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-19", "question": "The Governor's power to promulgate ordinances is in:", "options": ["Article 213", "Article 200", "Article 154", "Article 123"], "answer": 0, "explanation": "Article 213 is the State counterpart of Article 123. Article 200 deals with the Governor's assent to bills.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-state-local-govt-20", "question": "Under Article 171, a State Legislative Council can have at most one-third of the Assembly's total membership, and at least:", "options": ["20 members", "60 members", "40 members", "30 members"], "answer": 2, "explanation": "Article 171(1) sets the upper limit at one-third of the Assembly's strength and the lower limit at 40 members. Jammu and Kashmir's Council, which had 36 members under its own constitution, was an exception before 2019.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-21", "question": "Which Article lets the Governor reserve a bill for the President's consideration?", "options": ["Article 200", "Article 201", "Article 213", "Article 163"], "answer": 0, "explanation": "Under Article 200 the Governor may assent, withhold assent, return a bill (other than a Money Bill), or reserve it for the President. Article 201 sets out what the President does with a reserved bill.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-22", "question": "What is the minimum age to contest a panchayat election?", "options": ["30 years", "18 years", "25 years", "21 years"], "answer": 3, "explanation": "Under Article 243F a person must be qualified for the State legislature, except that 21 years is enough. This is lower than the 25 years needed for the Assembly.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-state-local-govt-23", "question": "The Advocate General of a State is provided for in:", "options": ["Article 148", "Article 165", "Article 177", "Article 76"], "answer": 1, "explanation": "Article 165 provides for the Advocate General, appointed by the Governor. Article 76 is the Attorney General of India.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-state-local-govt-24", "question": "If a panchayat is dissolved before its term ends, the election to reconstitute it must be finished within:", "options": ["One year", "Six months", "Before the original term would have ended", "Three months"], "answer": 1, "explanation": "Article 243E(3) requires the election within six months of dissolution. If less than six months of the original term is left, no election is needed for that remaining period.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-25", "question": "How many of these statements about the Governor are correct? I. The Governor holds office during the pleasure of the President. II. The same person can be Governor of two or more States. III. The State legislature can remove the Governor by impeachment. IV. The Governor's emoluments are charged on the Consolidated Fund of the State.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 156), II (Article 153, as amended by the 7th Amendment) and IV (Article 158(3)) are correct. The Constitution has no impeachment procedure for a Governor.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-26", "question": "How many of these statements about the 73rd Amendment are correct? I. Seats are reserved for SCs and STs in proportion to their population. II. Reservation for Other Backward Classes is compulsory. III. At least one-third of chairperson posts at each level are reserved for women. IV. Panchayats at the intermediate level must be set up in every State.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. Under Article 243D(6) OBC reservation is left to the State. Under Article 243B(2) States with a population of 20 lakh or less need not have an intermediate tier.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-27", "question": "Assertion (A): A Governor can pardon a person sentenced by a court martial. Reason (R): The Governor's pardoning power under Article 161 covers offences against laws on matters within the State's executive power.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false: only the President can deal with court-martial sentences, under Article 72(1)(a). R is true and correctly states the scope of Article 161.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-28", "question": "Which pair of a Schedule dealing with tribal areas or local bodies and its subject is NOT correctly matched?", "options": ["Eleventh Schedule — 29 functional items for panchayats", "Fifth Schedule — Administration of Scheduled Areas and Scheduled Tribes", "Twelfth Schedule — 29 functional items for municipalities", "Sixth Schedule — Tribal areas of Assam, Meghalaya, Tripura and Mizoram"], "answer": 2, "explanation": "The Twelfth Schedule has 18 items, not 29. The other three pairs are correct.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-29", "question": "How many of these statements about municipalities are correct? I. Ward Committees must be set up in municipalities with a population of three lakh or more. II. Every municipal corporation must have a Metropolitan Planning Committee. III. Article 243ZD provides for a District Planning Committee. IV. A dissolved municipality must be reconstituted within six months.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 243S), III and IV (Article 243U) are correct. A Metropolitan Planning Committee is needed only for a metropolitan area with a population of 10 lakh or more (Articles 243P and 243ZE), not for every corporation.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-30", "question": "How many of these States currently have a Legislative Council? Bihar, Kerala, Tamil Nadu, West Bengal", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Only Bihar. The six States with Councils are Andhra Pradesh, Bihar, Karnataka, Maharashtra, Telangana and Uttar Pradesh. Tamil Nadu abolished its Council in 1986, and West Bengal abolished its Council in 1969.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-31", "question": "How many of these statements about the Governor's discretion are correct? I. In some matters the Constitution expressly requires the Governor to act in their discretion. II. If a question arises whether a matter is within the Governor's discretion, the Governor's decision is final. III. In Nabam Rebia (2016) the Supreme Court held that the Governor cannot advance an Assembly session on their own, without ministerial advice.", "options": ["Only one", "Only two", "All three", "None"], "answer": 2, "explanation": "All three are correct. Article 163(2) makes the Governor's decision on the scope of discretion final. Express discretion appears, for example, in the Sixth Schedule. Nabam Rebia limited the Governor's discretion over summoning the House.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-32", "question": "The Speaker of a State Legislative Assembly resigns by writing to the:", "options": ["Chief Justice of the High Court", "Chief Minister", "Governor", "Deputy Speaker"], "answer": 3, "explanation": "Article 179 says the Speaker resigns to the Deputy Speaker, and the Deputy Speaker resigns to the Speaker. The Governor is the common wrong answer.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-33", "question": "Arrange these Panchayati Raj committees in time order: 1. L. M. Singhvi Committee 2. Ashok Mehta Committee 3. Balwant Rai Mehta Committee 4. G. V. K. Rao Committee", "options": ["2, 3, 4, 1", "3, 4, 2, 1", "3, 2, 4, 1", "3, 2, 1, 4"], "answer": 2, "explanation": "Balwant Rai Mehta (1957), Ashok Mehta (1977), G. V. K. Rao (1985) and L. M. Singhvi (1986). The Singhvi Committee recommended constitutional status for panchayats.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-34", "question": "How many of these statements about a Governor's handling of bills are correct? I. The Governor can return a Money Bill for reconsideration. II. The Governor must reserve a bill that would reduce the powers of the High Court. III. For a reserved non-money bill, the President can ask the Governor to return it, and the House must reconsider it within six months. IV. The President must give assent to a reserved bill once the State legislature passes it again.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "II (second proviso to Article 200) and III (Article 201) are correct. A Money Bill cannot be returned. The President is not bound to assent even after the legislature passes the bill again.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-35", "question": "Assertion (A): Panchayats have no power of their own under the Constitution to levy taxes. Reason (R): Article 243H leaves it to the State legislature to authorise panchayats to levy, collect and use taxes, duties, tolls and fees.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true, and R explains A. A panchayat's power to tax comes only from a State law made under Article 243H, not directly from the Constitution.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-36", "question": "How many of these statements about the Fifth Schedule are correct? I. The President declares an area to be a Scheduled Area. II. A Tribes Advisory Council has up to 20 members, about three-fourths of them ST members of the Assembly. III. The Governor can direct that an Act of Parliament shall not apply to a Scheduled Area. IV. The Fifth Schedule applies to the tribal areas of Assam.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Assam's tribal areas, like those of Meghalaya, Tripura and Mizoram, are covered by the Sixth Schedule, not the Fifth.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-37", "question": "How many of these statements about Sixth Schedule Autonomous District Councils are correct? I. A council generally has up to 30 members, of whom up to four are nominated by the Governor. II. The Governor can organise and reorganise autonomous districts. III. Acts of Parliament apply to autonomous districts automatically.", "options": ["Only one", "Only two", "All three", "None"], "answer": 1, "explanation": "I and II are correct. III is wrong: Acts of Parliament or the State legislature either do not apply or apply with changes, as the President or Governor directs. The Bodoland council is a larger exception to the 30-member pattern.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-38", "question": "Under Article 164(1A), the Council of Ministers in a State, including the Chief Minister, must have at least:", "options": ["12 members", "15 members", "7 members", "10 members"], "answer": 0, "explanation": "The 91st Amendment (2003) capped a State ministry at 15% of the Assembly's strength and set a minimum of 12 ministers, including the Chief Minister. The 15% is the trap.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-39", "question": "How many of these describe the composition of a State Legislative Council correctly? I. One-third elected by the members of the Legislative Assembly. II. One-twelfth elected by graduates of three years' standing in the State. III. One-twelfth elected by teachers of three years' standing, teaching at least at secondary level. IV. About one-sixth nominated by the Governor.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct under Article 171(3). The remaining one-third is elected by local bodies such as municipalities and district boards.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-40", "question": "National Panchayati Raj Day, observed on 24 April, marks:", "options": ["The 73rd Amendment coming into force in 1993", "The passing of PESA in 1996", "The 74th Amendment coming into force in 1993", "The start of Panchayati Raj at Nagaur in 1959"], "answer": 0, "explanation": "The 73rd Amendment came into force on 24 April 1993. The 74th came into force on 1 June 1993, and Nagaur was inaugurated on 2 October 1959.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-41", "question": "Which Article says that there shall be a Governor for each State?", "options": ["Article 152", "Article 153", "Article 154", "Article 163"], "answer": 1, "explanation": "Article 153 provides a Governor for each State (and, since the 7th Amendment, allows one person to be Governor of two or more States). Article 154 vests the State's executive power in the Governor.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-42", "question": "What is the minimum age for becoming a member of a State Legislative Assembly?", "options": ["21 years", "25 years", "30 years", "35 years"], "answer": 1, "explanation": "Article 173 sets 25 years for the Assembly and 30 years for the Legislative Council.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-state-local-govt-43", "question": "The 74th Constitutional Amendment Act, 1992 deals with:", "options": ["Panchayats", "Urban local bodies (municipalities)", "Co-operative societies", "Anti-defection"], "answer": 1, "explanation": "The 74th Amendment added Part IXA and the Twelfth Schedule on municipalities. Panchayats came through the 73rd Amendment.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-44", "question": "A Governor normally holds office for a term of:", "options": ["Four years", "Five years", "Six years", "Until the age of 65"], "answer": 1, "explanation": "Article 156(3) gives a five-year term, but the Governor holds office during the pleasure of the President and continues until a successor takes over.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-state-local-govt-45", "question": "A Mayor is the head of a:", "options": ["Gram Panchayat", "Zila Parishad", "Municipal Corporation", "Panchayat Samiti"], "answer": 2, "explanation": "The Mayor presides over a Municipal Corporation. A Zila Parishad is headed by a chairperson and a Gram Panchayat by a Sarpanch or Mukhiya.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-46", "question": "Who administers the oath of office to the Governor of a State?", "options": ["The President", "The Chief Minister", "The Chief Justice of the High Court of that State", "The Speaker of the Legislative Assembly"], "answer": 2, "explanation": "Article 159: the oath is administered by the Chief Justice of the High Court concerned or, in his absence, the senior-most available judge of that court.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-47", "question": "What is the minimum age for becoming a member of a State Legislative Council?", "options": ["21 years", "25 years", "30 years", "35 years"], "answer": 2, "explanation": "Article 173(b) requires 30 years for the Legislative Council, the same as for the Rajya Sabha.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-48", "question": "Which Article provides that there shall be a Council of Ministers headed by the Chief Minister to aid and advise the Governor, except where the Governor must act in his discretion?", "options": ["Article 154", "Article 163", "Article 164", "Article 167"], "answer": 1, "explanation": "Article 163 creates the State Council of Ministers and recognises the Governor's discretion. Article 164 deals with appointment and responsibility of ministers.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-49", "question": "District Planning Committees, which consolidate the plans of panchayats and municipalities, are provided for in:", "options": ["Article 243G", "Article 243W", "Article 243ZD", "Article 243ZE"], "answer": 2, "explanation": "Article 243ZD provides a District Planning Committee in every district. Article 243ZE is the Metropolitan Planning Committee.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-50", "question": "Under Article 243ZE, a Metropolitan Planning Committee is set up for a metropolitan area, which is defined as an area with a population of:", "options": ["Three lakh or more", "Five lakh or more", "Ten lakh or more", "Twenty lakh or more"], "answer": 2, "explanation": "Article 243P(c) defines a metropolitan area as one with a population of ten lakh or more. Three lakh is the threshold for Ward Committees.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-51", "question": "The Governor's power to summon and prorogue the State legislature and to dissolve the Legislative Assembly is in:", "options": ["Article 168", "Article 172", "Article 174", "Article 176"], "answer": 2, "explanation": "Article 174 covers summoning, prorogation and dissolution. Article 172 is the duration of the legislature and Article 176 the Governor's special address.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-52", "question": "A Nagar Panchayat is constituted for:", "options": ["A large urban area", "A transitional area, changing from rural to urban", "A cantonment", "A Scheduled Area"], "answer": 1, "explanation": "Article 243Q provides Nagar Panchayats for transitional areas, Municipal Councils for smaller urban areas and Municipal Corporations for larger urban areas.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-53", "question": "At which level does a Panchayat Samiti (intermediate panchayat) usually work?", "options": ["Village", "Block", "District", "Division"], "answer": 1, "explanation": "In the three-tier system the Gram Panchayat is at the village, the Panchayat Samiti at the block (intermediate) and the Zila Parishad at the district level.", "difficulty": "moderate", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-state-local-govt-54", "question": "Under Article 170, a State Legislative Assembly can have at most 500 members and, as a general rule, at least:", "options": ["40", "50", "60", "100"], "answer": 2, "explanation": "Article 170 sets 60 as the minimum. Smaller States such as Goa, Sikkim and Mizoram, and the UT of Puducherry, have been allowed fewer by law.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-55", "question": "Before the 104th Amendment ended it in 2020, a Governor could nominate one member of the Anglo-Indian community to the Legislative Assembly under:", "options": ["Article 331", "Article 332", "Article 333", "Article 334"], "answer": 2, "explanation": "Article 333 gave Governors this power. Article 331 was the corresponding Lok Sabha provision, and Article 332 reserves seats for SCs and STs in Assemblies.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-56", "question": "Under Article 371, the Governors of which two States have a special responsibility to set up separate development boards for regions such as Vidarbha and Saurashtra?", "options": ["Maharashtra and Gujarat", "Maharashtra and Karnataka", "Gujarat and Rajasthan", "Andhra Pradesh and Telangana"], "answer": 0, "explanation": "Article 371(2) covers Vidarbha, Marathwada and the rest of Maharashtra, and Saurashtra, Kutch and the rest of Gujarat. Karnataka's Hyderabad-Karnataka region falls under Article 371J.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-57", "question": "Under Article 371H, the Governor of which State has a special responsibility for law and order?", "options": ["Nagaland", "Mizoram", "Arunachal Pradesh", "Sikkim"], "answer": 2, "explanation": "Article 371H gives the Governor of Arunachal Pradesh this responsibility. Under Article 371A the Governor of Nagaland has a similar responsibility, so the trap is close.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-58", "question": "For how long, at most, can a State Legislative Council hold up an ordinary bill passed by the Assembly?", "options": ["14 days", "Three months", "Four months in all (three months, then one month)", "Six months"], "answer": 2, "explanation": "Under Article 197, the Council can delay a bill for three months the first time and one month after the Assembly passes it again, so four months in all. It cannot force a joint sitting; there is none at the State level.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-59", "question": "Which Article bars the State legislature from discussing the conduct of a judge of the Supreme Court or a High Court in the discharge of his duties?", "options": ["Article 121", "Article 194", "Article 211", "Article 212"], "answer": 2, "explanation": "Article 211 is the State-level bar; Article 121 is the corresponding bar on Parliament. Article 212 stops courts from inquiring into proceedings of the legislature.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-60", "question": "Which 2010 judgment held that a Governor cannot be removed arbitrarily merely because the party in power at the Centre has changed?", "options": ["S. R. Bommai", "Rameshwar Prasad", "B. P. Singhal", "Nabam Rebia"], "answer": 2, "explanation": "In B. P. Singhal v. Union of India (2010) the Court held that the President's pleasure under Article 156 is not unfettered and removal must have valid reasons, open to limited review.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-61", "question": "Which body recommended that a Governor should be an eminent person from outside the State who has not been too closely involved in politics in the recent past?", "options": ["Rajamannar Committee", "Sarkaria Commission", "Administrative Reforms Commission (1966)", "Ashok Mehta Committee"], "answer": 1, "explanation": "The Sarkaria Commission on Centre–State relations (1983–88) made this recommendation. The Rajamannar Committee (1969) was set up by Tamil Nadu on State autonomy.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-62", "question": "Part IXA of the Constitution, on Municipalities, covers Articles:", "options": ["243 to 243O", "243P to 243ZG", "243ZH to 243ZT", "244 to 244A"], "answer": 1, "explanation": "Part IX (Panchayats) is Articles 243–243O, Part IXA (Municipalities) is 243P–243ZG, and Part IXB (Co-operative Societies) is 243ZH–243ZT.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-63", "question": "Under the proviso to Article 243Q, a municipality need not be constituted in an urban area that the Governor specifies as:", "options": ["A Scheduled Area", "A cantonment", "An industrial township", "A notified area"], "answer": 2, "explanation": "Where an industrial establishment provides or proposes to provide municipal services, the Governor may declare the area an industrial township, and no municipality is needed there.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-64", "question": "Part IXB, on co-operative societies, was added by the:", "options": ["73rd Amendment", "86th Amendment", "97th Amendment", "101st Amendment"], "answer": 2, "explanation": "The 97th Amendment (2011) added Part IXB, the right to form co-operative societies in Article 19(1)(c) and Article 43B.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-65", "question": "In 2021 the Supreme Court struck down Part IXB to the extent it dealt with co-operative societies within a State because:", "options": ["It violated the right to equality", "It had not been ratified by half the State legislatures, though co-operatives are a State subject", "It was passed by a simple majority", "It was not signed by the President"], "answer": 1, "explanation": "Co-operative societies are in the State List, so the amendment needed ratification under Article 368(2). Part IXB survives only for multi-State co-operative societies.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-66", "question": "A bill passed by the State legislature that would, if it became law, take away from the powers of the High Court:", "options": ["Can be returned by the Governor but not reserved", "Must be reserved by the Governor for the President's consideration", "Needs the assent of the Chief Justice of India", "Must be referred to the Supreme Court"], "answer": 1, "explanation": "The second proviso to Article 200 makes reservation compulsory for such bills, so the Governor has no option to assent.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-67", "question": "When the same person is appointed Governor of two or more States, his emoluments are:", "options": ["Paid entirely by the Union", "Paid by the State where he lives", "Shared by the States in the proportion the President decides by order", "Paid only by the larger State"], "answer": 2, "explanation": "Article 158(3A), added by the 7th Amendment (1956), allocates the emoluments among the States in a proportion fixed by the President.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-68", "question": "Match the Article with the State it makes special provision for: A. Article 371B B. Article 371C C. Article 371F D. Article 371G — 1. Mizoram 2. Sikkim 3. Manipur 4. Assam", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1"], "answer": 2, "explanation": "371B is Assam (tribal areas committee), 371C Manipur (Hill Areas committee), 371F Sikkim and 371G Mizoram. 371A is Nagaland.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-69", "question": "How many of these statements about a State Election Commissioner are correct? I. He is appointed by the Governor. II. He can be removed only in the manner and on the grounds applicable to a High Court judge. III. His conditions of service cannot be varied to his disadvantage after appointment. IV. The State Election Commission conducts elections to the State Legislative Assembly.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (Article 243K). IV is wrong: Assembly elections are conducted by the Election Commission of India; the State Election Commission handles panchayat and municipal elections.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-70", "question": "Assertion (A): A State Legislative Council is not subject to dissolution. Reason (R): One-third of its members retire every second year.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: like the Rajya Sabha, the Council is a continuing House with staggered six-year terms (Article 172(2)). It can, however, be abolished by Parliament under Article 169.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-71", "question": "Arrange these steps in the growth of urban local government in India in time order: 1. Lord Ripon's resolution on local self-government 2. Setting up of the Madras Municipal Corporation 3. Royal Commission on Decentralisation 4. Lord Mayo's resolution on financial decentralisation", "options": ["2-4-1-3", "2-4-3-1", "4-2-1-3", "2-1-4-3"], "answer": 0, "explanation": "Madras Corporation (1688), Mayo's resolution (1870), Ripon's resolution (1882, the ‘Magna Carta’ of local self-government) and the Royal Commission on Decentralisation (1907–09).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-72", "question": "How many of these statements about the Speaker of a State Legislative Assembly are correct? I. The Speaker vacates office on ceasing to be a member of the Assembly. II. A resolution to remove the Speaker needs at least 14 days' notice. III. The Speaker presides over the sitting at which a resolution for his removal is considered. IV. The Speaker vacates office as soon as the Assembly is dissolved.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct (Article 179). III is wrong: under Article 181 he cannot preside, though he may speak and vote in the first instance. IV is wrong: he continues until just before the first meeting of the new Assembly.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-73", "question": "Match the committee with its key recommendation: A. Balwant Rai Mehta B. Ashok Mehta C. G. V. K. Rao D. L. M. Singhvi — 1. Constitutional recognition for local self-government 2. The district as the basic unit of planning, with a District Development Commissioner 3. A two-tier system with Mandal Panchayats 4. Three-tier ‘democratic decentralisation’", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Balwant Rai Mehta (1957) proposed the three-tier system, Ashok Mehta (1978) a two-tier one, G. V. K. Rao (1985) district-level planning, and L. M. Singhvi (1986) constitutional status.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-74", "question": "How many of these statements about the 74th Amendment are correct? I. It provides three types of municipalities: Nagar Panchayats, Municipal Councils and Municipal Corporations. II. At least one-third of seats are reserved for women. III. Municipal elections are conducted by the State Election Commission. IV. Fire services are listed in the Twelfth Schedule.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct (Articles 243Q, 243T, 243ZA and the Twelfth Schedule, which also includes urban forestry and slum improvement).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-75", "question": "Assertion (A): A person who is not a member of the State legislature can be appointed Chief Minister. Reason (R): Article 164(4) lets a non-member be a minister for up to six consecutive months.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the Chief Minister is also a minister, so he must become a member within six months or vacate office.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-76", "question": "Which of these subjects is NOT listed in the Eleventh Schedule (panchayats)?", "options": ["Minor forest produce", "Fisheries", "Fire services", "Rural electrification"], "answer": 2, "explanation": "Fire services is an item in the Twelfth Schedule (municipalities). The other three are among the 29 items of the Eleventh Schedule.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-77", "question": "How many of these statements about the PESA Act, 1996 are correct? I. It applies to Fifth Schedule areas in ten States. II. The Gram Sabha or panchayat must be consulted before land is acquired for development projects. III. Panchayats and Gram Sabhas get ownership of minor forest produce. IV. It applies to the Sixth Schedule areas of the North-East.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: PESA extends Part IX only to Fifth Schedule areas; Sixth Schedule areas have Autonomous District Councils.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-78", "question": "A State Legislative Council has 72 members. Under Article 171, how many are elected by graduates and how many are nominated by the Governor?", "options": ["6 graduates, 12 nominated", "12 graduates, 6 nominated", "6 graduates, 6 nominated", "8 graduates, 12 nominated"], "answer": 0, "explanation": "Graduates elect 1/12 of the members: 72 ÷ 12 = 6. The Governor nominates 1/6: 72 ÷ 6 = 12. Teachers also elect 6, while local bodies and MLAs elect 24 each.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-79", "question": "Match the Article with its subject: A. Article 163 B. Article 165 C. Article 167 D. Article 213 — 1. Ordinances 2. Duties of the Chief Minister to inform the Governor 3. Advocate General 4. Council of Ministers to aid and advise the Governor", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Article 163 is aid and advice, 165 the Advocate General, 167 the Chief Minister's duties and 213 the Governor's ordinances.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-80", "question": "Assertion (A): Reservation of panchayat seats for backward classes is compulsory under the 73rd Amendment. Reason (R): Article 243D(6) allows the State legislature to make provision for reservation for backward classes.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 3, "explanation": "A is false: only SC/ST and women's reservation is compulsory. R is true: reservation for backward classes is left to the State legislature, so it is optional.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-81", "question": "Which of these is NOT compulsory in every State under Parts IX and IXA?", "options": ["A State Finance Commission", "A State Election Commission", "A District Planning Committee in every district", "A Metropolitan Planning Committee"], "answer": 3, "explanation": "Finance Commissions (243-I), Election Commissions (243K) and DPCs (243ZD) are required everywhere. An MPC is needed only where there is a metropolitan area of ten lakh or more.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-82", "question": "Arrange in time order: 1. The 74th Amendment comes into force 2. The Ministry of Panchayati Raj is set up 3. The 73rd Amendment comes into force 4. The PESA Act is passed", "options": ["3-1-2-4", "3-4-1-2", "1-3-4-2", "3-1-4-2"], "answer": 3, "explanation": "73rd Amendment in force on 24 April 1993, 74th on 1 June 1993, PESA passed in December 1996, and the Ministry of Panchayati Raj created in May 2004.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-83", "question": "How many of these statements about the Governor are correct? I. He must be a citizen of India who has completed 35 years. II. He must have lived in the State for at least five years. III. He can be removed by the State Legislative Assembly by impeachment. IV. His oath is administered by the Chief Minister.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Only I is correct (Article 157). There is no residence requirement (by convention he is usually an outsider), no impeachment (he holds office at the President's pleasure), and the oath is given by the Chief Justice of the High Court.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-84", "question": "How many of these statements about other urban bodies are correct? I. Cantonment Boards work under the Cantonments Act, 2006 and the Ministry of Defence. II. A township is set up by a large public enterprise to provide civic services to its staff colony. III. A notified area committee is wholly nominated by the State government. IV. The officer commanding the station is the ex officio president of a Cantonment Board.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. None of these bodies is a ‘municipality’ under Part IXA, which is why they are often tested together.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-85", "question": "Under the proviso to Article 164(1), as amended by the 94th Amendment (2006), there must be a minister in charge of tribal welfare in which States?", "options": ["Chhattisgarh, Jharkhand, Madhya Pradesh and Odisha", "Bihar, Madhya Pradesh, Odisha and Chhattisgarh", "Jharkhand, Rajasthan, Gujarat and Madhya Pradesh", "Odisha, Assam, Jharkhand and Madhya Pradesh"], "answer": 0, "explanation": "The 94th Amendment replaced Bihar (which no longer had large tribal areas after Jharkhand was carved out) with Chhattisgarh and Jharkhand, keeping Madhya Pradesh and Odisha.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-state-local-govt-86", "question": "The elected head of a Gram Panchayat is commonly called the:", "options": ["Sarpanch", "Mayor", "Zila Pramukh", "Block Development Officer"], "answer": 0, "explanation": "The Sarpanch (Mukhiya or Pradhan in some States) heads the village panchayat. A Mayor heads a Municipal Corporation; the BDO is an official, not an elected head.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "polity-state-local-govt-87", "question": "In the three-tier Panchayati Raj system, the Zila Parishad works at the:", "options": ["Village level", "Block level", "District level", "Division level"], "answer": 2, "explanation": "The Zila Parishad is the district tier; the Panchayat Samiti works at the block level and the Gram Panchayat at the village level.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "polity-state-local-govt-88", "question": "Who was the first woman Governor of an Indian State?", "options": ["Sucheta Kripalani", "Vijaya Lakshmi Pandit", "Padmaja Naidu", "Sarojini Naidu"], "answer": 3, "explanation": "Sarojini Naidu became Governor of the United Provinces in 1947. Sucheta Kripalani was the first woman Chief Minister, and Padmaja Naidu, her daughter, later governed West Bengal.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-state-local-govt-89", "question": "The Balwant Rai Mehta Committee, which recommended a three-tier Panchayati Raj system, submitted its report in:", "options": ["1952", "1957", "1977", "1986"], "answer": 1, "explanation": "The committee reported in November 1957, proposing “democratic decentralisation”. The Ashok Mehta Committee (1977–78) favoured two tiers, and the L. M. Singhvi Committee (1986) constitutional status.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-state-local-govt-90", "question": "After Rajasthan, which State was the next to introduce Panchayati Raj in 1959?", "options": ["Andhra Pradesh", "Kerala", "Gujarat", "Maharashtra"], "answer": 0, "explanation": "Rajasthan launched it at Nagaur on 2 October 1959 and Andhra Pradesh followed later the same year.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-state-local-govt-91", "question": "Which Article provides for a State Election Commission to conduct panchayat elections?", "options": ["Article 243G", "Article 243I", "Article 243K", "Article 324"], "answer": 2, "explanation": "Article 243K sets up the State Election Commission, and Article 243ZA gives it municipal elections too. Article 243I is the State Finance Commission, and Article 324 the Election Commission of India.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-state-local-govt-92", "question": "How many States in India have a bicameral legislature (a Legislative Council) at present?", "options": ["Five", "Six", "Seven", "Eight"], "answer": 1, "explanation": "Andhra Pradesh, Bihar, Karnataka, Maharashtra, Telangana and Uttar Pradesh have Legislative Councils. Jammu and Kashmir's Council ended with the 2019 reorganisation.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-state-local-govt-93", "question": "Which was the first State to reserve 50% of seats in panchayats for women, in 2006?", "options": ["Kerala", "Rajasthan", "Madhya Pradesh", "Bihar"], "answer": 3, "explanation": "Bihar raised women's reservation in panchayats to 50% in 2006, above the one-third minimum of Article 243D. Many States have since followed.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-state-local-govt-94", "question": "Under Article 164(2), the State Council of Ministers is collectively responsible to the:", "options": ["Governor", "Legislative Assembly", "Both Houses of the State legislature", "Chief Minister"], "answer": 1, "explanation": "Collective responsibility runs to the Legislative Assembly alone, even in States with a Legislative Council. Individually, ministers hold office during the Governor's pleasure.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-state-local-govt-95", "question": "Which Article bars courts from interfering in panchayat electoral matters, so that a panchayat election can be questioned only by an election petition?", "options": ["Article 243-O", "Article 243K", "Article 329", "Article 243ZD"], "answer": 0, "explanation": "Article 243-O is the panchayat counterpart of Article 329 (for Parliament and State legislatures); Article 243ZG does the same for municipalities. Article 243ZD concerns District Planning Committees.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-96", "question": "In which 2006 case did the Supreme Court hold the dissolution of the Bihar Legislative Assembly in 2005 to be unconstitutional?", "options": ["S. R. Bommai v. Union of India", "Rameshwar Prasad v. Union of India", "Nabam Rebia v. Deputy Speaker", "B. P. Singhal v. Union of India"], "answer": 1, "explanation": "Rameshwar Prasad held that the Governor's report recommending dissolution to stop a government being formed was mala fide. B. P. Singhal (2010) concerned the removal of Governors.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-97", "question": "In Nabam Rebia v. Deputy Speaker (2016), concerning Arunachal Pradesh, the Supreme Court held that:", "options": ["The Governor may dismiss a Chief Minister at will", "Speakers' decisions on defection are final and beyond review", "The Governor cannot on his own advance an Assembly session without the aid and advice of the Council of Ministers", "The Governor must always reserve money bills for the President"], "answer": 2, "explanation": "The Court held the Governor's discretion under Article 163 is limited and he cannot summon or advance a session on his own; it restored the Nabam Tuki government.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-98", "question": "Article 244A, which enables Parliament to form an autonomous State within Assam for certain tribal areas, was inserted by the:", "options": ["7th Amendment, 1956", "13th Amendment, 1962", "22nd Amendment, 1969", "27th Amendment, 1971"], "answer": 2, "explanation": "The 22nd Amendment (1969) added Article 244A; it was used to create Meghalaya first as an autonomous State within Assam. The 13th Amendment had created Nagaland with Article 371A.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-99", "question": "How many Autonomous District Councils exist under the Sixth Schedule?", "options": ["Six", "Eight", "Twelve", "Ten"], "answer": 3, "explanation": "There are ten: three in Assam (including the Bodoland Territorial Council), three in Meghalaya (Khasi, Jaintia, Garo), one in Tripura and three in Mizoram (Chakma, Lai, Mara).", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-100", "question": "Article 239A, which let Parliament create a legislature and Council of Ministers for Puducherry, was inserted by the:", "options": ["7th Amendment, 1956", "14th Amendment, 1962", "69th Amendment, 1991", "42nd Amendment, 1976"], "answer": 1, "explanation": "The 14th Amendment (1962) added Article 239A; Puducherry's legislature exists under the Government of Union Territories Act, 1963. The 69th Amendment created Delhi's arrangement under Article 239AA.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-101", "question": "Consider the following statements: 1. Under Article 243I, the Governor constitutes a Finance Commission every five years to review panchayat finances. 2. Under Article 243Y, the same Finance Commission also reviews the finances of municipalities. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. One State Finance Commission covers both rural and urban local bodies and recommends how State taxes and grants should be shared with them.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-102", "question": "A State Legislative Council can hold up a Money Bill passed by the Legislative Assembly for at most:", "options": ["14 days", "One month", "Three months", "Four months"], "answer": 0, "explanation": "Under Article 198 the Council must return a Money Bill within 14 days, after which it is deemed passed. For ordinary bills the Council can cause delay of up to four months in all.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-103", "question": "The Legislative Council of which State or region ceased to exist in 2019?", "options": ["Tamil Nadu", "Jammu and Kashmir", "Andhra Pradesh", "Punjab"], "answer": 1, "explanation": "The Jammu and Kashmir Reorganisation Act, 2019 abolished its Council when the State became a Union Territory. Andhra Pradesh's Assembly resolved in 2020 to abolish its Council, but no law followed and it continues.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-104", "question": "Consider the following statements: 1. The chairperson of a district-level panchayat is elected by and from among its elected members. 2. The Constitution itself fixes how the chairperson of a village panchayat is to be elected. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. Under Article 243C(5), chairpersons at the intermediate and district levels are elected indirectly; the mode for the village level is left to the State legislature.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-105", "question": "Match the Article with its subject: A. Article 156 B. Article 159 C. Article 161 D. Article 162 — 1. Extent of the executive power of the State 2. Pardoning power of the Governor 3. Oath of the Governor 4. Term of office of the Governor", "options": ["A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Article 156 is the term, 159 the oath, 161 the pardoning power and 162 the extent of the State's executive power.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-106", "question": "Consider the following statements: 1. A panchayat continues for five years from the date of its first meeting unless dissolved sooner. 2. If a panchayat is dissolved with less than six months of its term left, no election need be held for the remaining period. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct under Article 243E. A panchayat formed after early dissolution serves only the remainder of the original term.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-107", "question": "How many of these statements about a State bill reserved for the President under Article 201 are correct? I. The President may direct the Governor to return it (if not a Money Bill) to the legislature. II. The legislature must then reconsider it within six months. III. If the legislature passes it again, the President must give assent. IV. The Constitution fixes a time limit for the President's decision on a reserved bill.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. Even a re-passed bill need not receive the President's assent, and Article 201 lays down no time limit.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-108", "question": "Consider the following statements: 1. The 69th Amendment (1991) inserted Article 239AA, giving Delhi a Legislative Assembly. 2. In 2023 a Constitution Bench held that Delhi's elected government controls services except those relating to public order, police and land. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Parliament later passed the GNCTD (Amendment) Act, 2023, creating an authority for services matters.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-109", "question": "Arrange in chronological order: 1. Panchayati Raj launched at Nagaur 2. Ashok Mehta Committee report 3. 73rd Amendment comes into force 4. Bihar reserves half of panchayat seats for women", "options": ["1, 3, 2, 4", "2, 1, 3, 4", "1, 2, 3, 4", "1, 2, 4, 3"], "answer": 2, "explanation": "Nagaur 1959, Ashok Mehta report 1978, 73rd Amendment in force 24 April 1993, and Bihar's 50% reservation in 2006.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-110", "question": "Assertion (A): Municipal elections are conducted by the State Election Commission. Reason (R): Article 243ZA vests the conduct of municipal elections in the State Election Commission set up under Article 243K.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. The same State Election Commission handles both panchayat and municipal elections; the Election Commission of India has no role in them.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-111", "question": "Which Article contains special provisions for the Hyderabad-Karnataka region of Karnataka, inserted by the 98th Amendment (2012)?", "options": ["Article 371D", "Article 371E", "Article 371I", "Article 371J"], "answer": 3, "explanation": "Article 371J provides a development board and reservation in jobs and education for the region. 371D and 371E relate to Andhra Pradesh and 371I to Goa.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-112", "question": "How many of these Union Territories have a Legislative Assembly? Delhi, Puducherry, Jammu and Kashmir, Ladakh", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Delhi (Article 239AA), Puducherry (Article 239A) and Jammu and Kashmir (under the 2019 Reorganisation Act) have Assemblies. Ladakh is a UT without a legislature.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-state-local-govt-113", "question": "Consider the following statements: 1. The Constitution lays down the grounds on which a Governor may be removed. 2. A Governor's five-year term is subject to the pleasure of the President. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 1, "explanation": "Only 2 is correct. Article 156 gives no grounds for removal; in B. P. Singhal (2010) the Court held the pleasure cannot be exercised arbitrarily, though it remains the formal basis.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-114", "question": "Consider the following statements: 1. While a National Emergency is in operation, Parliament may by law extend the term of a State Legislative Assembly by up to one year at a time. 2. Such an extension may continue up to one year after the Emergency ceases to operate. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct under Article 172(1). Any extension must end within six months after the Emergency ceases, not one year.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-state-local-govt-115", "question": "Assertion (A): The validity of an action of the Governor cannot be called in question on the ground that he ought or ought not to have acted in his discretion. Reason (R): Under Article 163(2), the Governor's decision on whether a matter falls within his discretion is final.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A; both statements come from Article 163(2). Courts have still read limits into this discretion, as in Nabam Rebia (2016).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"polity-state-local-govt-116","question":"Article 170 says a State Legislative Assembly shall have at least 60 members, but special provisions allow smaller Houses in some States. Which pair of States both have Assemblies of fewer than 60 members?","options":["Nagaland and Manipur","Goa and Mizoram","Tripura and Meghalaya","Arunachal Pradesh and Nagaland"],"answer":1,"explanation":"Goa and Mizoram have 40 members each (Articles 371I and 371G allow this), and Sikkim has 32 under Article 371F. The north-eastern States in the other options all have 60.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"polity-state-local-govt-117","question":"Under Article 189, the quorum for a sitting of a State Legislative Assembly or Legislative Council is:","options":["one-tenth of the total membership","one-fourth of the total membership","twenty members or one-tenth of the total membership, whichever is less","ten members or one-tenth of the total membership, whichever is greater"],"answer":3,"explanation":"Article 189(3) sets ten members or one-tenth, whichever is greater, so a small House still needs at least ten. Parliament’s quorum under Article 100 is a plain one-tenth, which is the trap.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-118","question":"If a question arises whether a member of a State Legislative Assembly has become disqualified under Article 191(1), for example for holding an office of profit, who decides it?","options":["The Speaker of the Assembly","The High Court of the State","The Governor, acting according to the opinion of the Election Commission","The Chief Minister, on the advice of the Advocate General"],"answer":2,"explanation":"Article 192 makes the Governor’s decision final but binds him to the Election Commission’s opinion. The Speaker decides only defection cases under the Tenth Schedule.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-119","question":"In which of these cases can the Governor NOT promulgate an ordinance without instructions from the President? I. A bill with the same provisions would have needed the President’s previous sanction for its introduction. II. The Governor would have thought it necessary to reserve a bill with the same provisions for the President. III. An Act of the State legislature with the same provisions would be invalid unless the President had assented to it.","options":["I only","I and II only","II and III only","I, II and III"],"answer":3,"explanation":"The proviso to Article 213(1) lists all three cases, so the Governor cannot use an ordinance to bypass the President’s control over such State laws.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-120","question":"Under Article 243B, a State need not set up panchayats at the intermediate level if its population does not exceed:","options":["10 lakh","20 lakh","25 lakh","50 lakh"],"answer":1,"explanation":"The intermediate (block) tier is optional only in States with a population of 20 lakh or less; the village and district tiers are compulsory everywhere Part IX applies.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"polity-state-local-govt-121","question":"Under Article 243A, the Gram Sabha exercises:","options":["the powers listed in the Eleventh Schedule","the powers the Governor assigns to it by order","the powers and functions the State legislature may by law provide","the powers and functions Parliament may by law provide"],"answer":2,"explanation":"Part IX leaves the Gram Sabha’s powers to State law. The Eleventh Schedule lists subjects that may be devolved to panchayats, not to the Gram Sabha as such.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-122","question":"Under Part IX, who provides for the maintenance of accounts by panchayats and the auditing of those accounts?","options":["The Comptroller and Auditor-General, by a direct constitutional mandate","The State Finance Commission","The State Election Commission","The State legislature, by law"],"answer":3,"explanation":"Article 243J leaves accounts and audit to State law. The CAG has no direct mandate under Part IX, and the State Finance Commission only reviews panchayat finances.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-123","question":"Under Article 243N, a State panchayat law in force before the 73rd Amendment that was inconsistent with Part IX could continue until amended or repealed, but for at most:","options":["six months from the commencement of the amendment","one year from the commencement of the amendment","two years from the commencement of the amendment","the end of the next general election to the State Assembly"],"answer":1,"explanation":"Article 243N gave States one year to bring their laws in line, though panchayats already existing could finish their terms unless dissolved by an Assembly resolution. Article 243ZF does the same for municipalities.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-124","question":"Consider the following statements: 1. At least four-fifths of the members of a District Planning Committee are elected by and from the elected members of the district panchayat and the municipalities in the district, in proportion to the rural and urban population. 2. At least two-thirds of the members of a Metropolitan Planning Committee are elected by the elected members of the municipalities and the chairpersons of the panchayats in the area. 3. The chairperson of a District Planning Committee must be the District Collector. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Articles 243ZD and 243ZE fix the four-fifths and two-thirds elected shares. How the chairperson is chosen is left to State law, so 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-125","question":"Under Article 243R, a State may provide for representation in a municipality of persons with special knowledge or experience in municipal administration. Such persons:","options":["have no right to vote in meetings of the municipality","vote like elected members","must be elected by the ward committees","may be elected chairperson of the municipality"],"answer":0,"explanation":"Article 243R(2)(a)(i) expressly denies these nominated experts a vote. MPs and MLAs who are represented in a municipality under State law do get to vote.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-126","question":"Consider the following statements: 1. The 73rd Amendment added a duty for the Finance Commission under Article 280 to recommend measures to augment the Consolidated Fund of a State to supplement the resources of panchayats. 2. These recommendations are to be based on those of the State Finance Commission. 3. The 74th Amendment added a similar clause for municipalities. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Article 280(3)(bb) for panchayats came with the 73rd Amendment and 280(3)(c) for municipalities with the 74th, both tied to the State Finance Commission’s recommendations.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-127","question":"How many of these statements are correct? I. In K. Krishna Murthy v. Union of India (2010), the Supreme Court upheld reservation for backward classes in local bodies under Articles 243D(6) and 243T(6). II. The Court held that backwardness for political representation in local bodies is not the same as backwardness for education and jobs. III. In Vikas Kishanrao Gawali (2021), the Court required a ‘triple test’, including a dedicated commission, before OBC reservation in local bodies. IV. Gawali allowed total reservation in local bodies to exceed 50% where a State’s backward population is large.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I to III are correct. The triple test is a dedicated commission, a local-body-wise proportion based on its findings, and a total that does not exceed 50% of the seats, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-128","question":"Consider the following statements: 1. In Javed v. State of Haryana (2003), the Supreme Court upheld a law disqualifying a person with more than two children from holding certain panchayat posts. 2. In Rajbala v. State of Haryana (2015), it upheld minimum educational qualifications for panchayat candidates. 3. In Rajbala, the Court struck down the condition that a candidate must have a functional toilet at home. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Rajbala upheld all the Haryana conditions, including education, no arrears of certain dues and a functional toilet. Javed upheld the two-child norm as a valid classification.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-129","question":"The 64th Constitution Amendment Bill (1989), which sought to give panchayats constitutional status, did not become law because:","options":["it was defeated in the Rajya Sabha","the President withheld assent","fewer than half the States ratified it","the Supreme Court struck it down"],"answer":0,"explanation":"The bill passed the Lok Sabha but failed in the Rajya Sabha in 1989. Constitutional status came only with the 73rd Amendment in 1992.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-130","question":"A panchayat has 30 directly elected seats, of which 9 are reserved for Scheduled Castes and Scheduled Tribes. What does Article 243D require for women?","options":["At least 10 seats in all, of which at least 3 must be among the seats reserved for SCs and STs","At least 10 seats, all of which must come from the 21 unreserved seats","At least 13 seats: 10 general seats plus 3 SC/ST seats","At least 15 seats, since 50% is the constitutional minimum"],"answer":0,"explanation":"One-third of the SC/ST seats (3 of 9) go to SC/ST women, and one-third of all seats (10 of 30) go to women, the 10 including those 3. The 50% that many States give is their own choice, not a constitutional floor.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-131","question":"Which authority, by public notification, specifies whether an area is a transitional area, a smaller urban area or a larger urban area for the purpose of constituting municipalities?","options":["The State Election Commission","The State Finance Commission","The Union Ministry of Housing and Urban Affairs","The Governor"],"answer":3,"explanation":"Article 243Q(2) gives this to the Governor, who considers population, density, revenue, the share of non-agricultural employment and economic importance.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-132","question":"Which of these subjects appears in the Twelfth Schedule (municipalities)?","options":["Libraries","Fuel and fodder","Fire services","Public distribution system"],"answer":2,"explanation":"Fire services is a municipal function in the Twelfth Schedule. Libraries, fuel and fodder and the public distribution system are items in the Eleventh Schedule for panchayats.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"polity-state-local-govt-133","question":"Which of these bodies functions under the Sixth Schedule?","options":["Gorkhaland Territorial Administration","Ladakh Autonomous Hill Development Council, Leh","Bodoland Territorial Council","Hill Areas Committee of the Manipur Legislative Assembly"],"answer":2,"explanation":"The Bodoland Territorial Council in Assam was brought under the Sixth Schedule in 2003. The Gorkhaland and Ladakh bodies rest on ordinary laws, and Manipur’s Hill Areas Committee on Article 371C.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-134","question":"Under Article 371A, how many of these subjects are such that no Act of Parliament on them applies to Nagaland unless its Legislative Assembly so decides by resolution? I. Religious or social practices of the Nagas II. Naga customary law and procedure III. Ownership and transfer of land and its resources IV. Defence of India","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Article 371A protects Naga religious and social practices, customary law and procedure (including civil and criminal justice under it), and land and its resources. Defence is not covered.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-135","question":"In Shamsher Singh v. State of Punjab (1974), a seven-judge bench held that:","options":["the President and the Governor exercise their formal powers on the aid and advice of their ministers, except where the Constitution leaves a matter to their discretion","the Governor may act against ministerial advice whenever he thinks the public interest requires it","the satisfaction of the Governor required by the Constitution is his personal satisfaction and cannot rest on ministerial advice","the Governor is bound by the advice of the High Court in all matters concerning subordinate judges"],"answer":0,"explanation":"Shamsher Singh held that the Governor’s ‘satisfaction’ means the satisfaction of the Council of Ministers, overruling the personal-satisfaction view of Sardari Lal.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-136","question":"According to the Sarkaria Commission, in a hung Assembly the Governor should FIRST invite:","options":["the single largest party, if it claims the support of others","an alliance of parties formed before the elections","a coalition formed after the elections, with all partners joining the government","a coalition formed after the elections, with some partners supporting from outside"],"answer":1,"explanation":"Sarkaria’s order of preference is a pre-poll alliance, then the single largest party claiming support, then a post-poll coalition with all partners in government, then one with outside support.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-137","question":"In which case did the Supreme Court hold that whether a Chief Minister has lost his majority must be tested on the floor of the House and not by the Governor’s private assessment?","options":["Rameshwar Prasad v. Union of India (2006)","S. R. Bommai v. Union of India (1994)","Nabam Rebia v. Deputy Speaker (2016)","B. P. Singhal v. Union of India (2010)"],"answer":1,"explanation":"Bommai made the floor test the proper way to judge majority. Rameshwar Prasad struck down the 2005 Bihar dissolution and B. P. Singhal dealt with removal of Governors.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-138","question":"How many of these statements are correct? I. Members of a State Legislative Council vote in elections to the Rajya Sabha. II. Members of a State Legislative Council vote in the election of the President. III. Members of a State Legislative Council vote in the election of the Vice-President. IV. A member of the Legislative Council can be appointed Chief Minister.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only IV is correct. Rajya Sabha members and the President are elected by elected MLAs only, and the Vice-President by MPs only; an MLC can be Chief Minister, since he is a member of the State legislature.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-139","question":"Which of these is NOT a matter in which the Constitution gives the Governor discretion?","options":["Reserving a bill for the President’s consideration","Deciding the share of mining royalties payable to an autonomous district council in Assam, Meghalaya, Tripura or Mizoram","Acting as administrator of an adjoining Union Territory","Appointing the Advocate General of the State"],"answer":3,"explanation":"The Advocate General is appointed on the advice of the Council of Ministers. Reservation of bills, royalty disputes under the Sixth Schedule and the administration of a neighbouring Union Territory are discretionary.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-140","question":"In S. R. Chaudhuri v. State of Punjab (2001), the Supreme Court held that a non-member appointed a minister under Article 164(4):","options":["cannot be reappointed during the same Assembly without getting elected within the six months","may be reappointed any number of times, each time for six months","must resign at once if he loses a by-election, even before six months end","must first become a member of the Legislative Council"],"answer":0,"explanation":"Reappointing the same non-member without his being elected would be a fraud on the Constitution. Article 164(4) gives a one-time window of six consecutive months.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-141","question":"Under Article 164(1B), a member of a State legislature disqualified under the Tenth Schedule is also barred from being appointed a minister:","options":["for six years from the date of disqualification","for life, unless pardoned by the President","until the Governor condones the defection","until his term as a member would have ended, or until he is re-elected, whichever is earlier"],"answer":3,"explanation":"The 91st Amendment (2003) added Articles 75(1B) and 164(1B) so that a defector cannot simply be made a minister; the bar lasts for the rest of the term or until re-election.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-142","question":"When the Governor of a State is appointed administrator of an adjoining Union Territory under Article 239(2), he:","options":["acts on the advice of his State Council of Ministers","acts independently of his State Council of Ministers","acts on the advice of the Union Territory’s elected legislature","needs the concurrence of the Chief Minister of his State"],"answer":1,"explanation":"Article 239(2) expressly says the Governor shall exercise his functions as administrator independently of his Council of Ministers; he answers to the President for the territory.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-143","question":"Article 240 lets the President make regulations for the peace, progress and good government of certain Union Territories. Which of these is NOT covered by it?","options":["Lakshadweep","Andaman and Nicobar Islands","Dadra and Nagar Haveli and Daman and Diu","National Capital Territory of Delhi"],"answer":3,"explanation":"Delhi has its own legislature under Article 239AA. Article 240 covers island and small territories, and Puducherry only while its legislature is dissolved or suspended.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-144","question":"Match the Article with its special provision: A. Article 371A B. Article 371D C. Article 371E D. Article 371I — 1. Goa 2. Nagaland 3. Equitable opportunities in public employment and education in Andhra Pradesh and Telangana 4. A Central University in Andhra Pradesh","options":["A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-1, B-3, C-4, D-2","A-3, B-2, C-4, D-1"],"answer":0,"explanation":"371A protects Naga customs and land, 371D lets the President secure local opportunities in jobs and education, 371E provides for a Central University, and 371I deals with Goa’s Assembly.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-145","question":"How many of these statements about the Governor are correct? I. If a member of Parliament or of a State legislature is appointed Governor, his seat is deemed vacated on the date he enters office. II. His emoluments and allowances cannot be diminished during his term. III. He is entitled to the use of his official residence without paying rent. IV. He must not have been a member of a political party in the five years before his appointment.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I to III restate Article 158. There is no bar on recent party membership; Sarkaria only recommended that a Governor not be too closely involved in politics in the recent past.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-146","question":"How many of these are powers of the Governor under the Fifth Schedule? I. Directing that an Act of Parliament or of the State shall not apply to a Scheduled Area, or shall apply with modifications. II. Making regulations to prohibit or restrict the transfer of land by or among Scheduled Tribes and to regulate money-lending to them. III. Such regulations taking effect only after the President’s assent. IV. Reporting to the President every year, or whenever required, on the administration of Scheduled Areas.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are in paragraphs 3 and 5 of the Fifth Schedule. The Governor must consult the Tribes Advisory Council before making such regulations.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-147","question":"Consider the following statements about the Panchayats (Extension to the Scheduled Areas) Act, 1996: 1. In Scheduled Area panchayats, seats reserved for Scheduled Tribes at every level must be at least one-half of the total seats. 2. All chairperson posts at all levels must be reserved for Scheduled Tribes. 3. Ownership of major minerals is vested in the Gram Sabha. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"PESA gives the Gram Sabha ownership of minor forest produce and a say on minor minerals, not ownership of major minerals. The two reservation rules are in Section 4(g).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-148","question":"Under Article 243K, the superintendence, direction and control of the preparation of electoral rolls for panchayat elections is vested in:","options":["The State Election Commission","The Election Commission of India","The Chief Electoral Officer of the State","The District Collector"],"answer":0,"explanation":"Local body elections, including electoral rolls, are run by the State Election Commission. The Election Commission of India handles only Parliament, State legislatures, the President and the Vice-President.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"polity-state-local-govt-149","question":"Which type of urban local body has all its members, including the chairman, nominated by the State government?","options":["Municipal corporation","Cantonment board","Notified area committee","Municipal council"],"answer":2,"explanation":"A notified area committee is set up for a fast-growing town or one that does not yet meet the conditions for a municipality, and is wholly nominated. Corporations and councils are elected, and cantonment boards are partly elected.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"polity-state-local-govt-150","question":"A large public sector enterprise sets up a civic body to run services in the housing colony built for its staff near its plant. The body has no elected members and is run by an administrator appointed by the enterprise. This form of urban government is a:","options":["Township","Notified area committee","Special purpose agency","Town area committee"],"answer":0,"explanation":"A township is run by the enterprise itself through a town administrator. A notified area committee is nominated by the State government, and a special purpose agency handles one function such as housing or water.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-151","question":"Consider the following statements about Article 361: 1. No criminal proceedings can be instituted or continued against a Governor in any court during his term. 2. Civil proceedings for his personal acts can be instituted during his term after two months’ notice in writing. 3. He is not answerable to any court for the exercise of the powers and duties of his office. 4. He may be arrested during his term for an offence committed before he took office. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3 only","3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Article 361 gives full criminal immunity during the term, including no arrest or imprisonment for any act, whenever done. Civil suits for personal acts need two months’ notice.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-152","question":"Consider the following statements about creating or abolishing a State Legislative Council under Article 169: 1. Once the Assembly passes the required resolution, Parliament is bound to create or abolish the Council. 2. Parliament’s law for this purpose is not deemed an amendment of the Constitution under Article 368. 3. Parliament can pass such a law by a simple majority. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","3 only","1, 2 and 3"],"answer":1,"explanation":"The Assembly must pass the resolution by a majority of its total membership and two-thirds of those present and voting, but Parliament is free to act or not. Its law, though it changes the Constitution, is not an Article 368 amendment.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-153","question":"How many of these statements about the Advocate General of a State are correct? I. He must be qualified to be appointed a judge of a High Court. II. He holds office during the pleasure of the Governor. III. His remuneration is determined by the Governor. IV. He has the right to vote in the State legislature.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I to III come from Article 165. Under Article 177 the Advocate General may speak in either House of the State legislature but cannot vote.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-154","question":"Which of these States has the smallest Legislative Assembly?","options":["Goa","Mizoram","Tripura","Sikkim"],"answer":3,"explanation":"Sikkim’s Assembly has 32 members (Article 371F allows at least 30). Goa and Mizoram have 40 each, and Tripura has 60.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-state-local-govt-155","question":"Parts IX and IXA say that nothing in them shall affect the functions and powers of a particular hill council set up under a State law. Which body do they name?","options":["Bodoland Territorial Council","Karbi Anglong Autonomous Council","Darjeeling Gorkha Hill Council","Ladakh Autonomous Hill Development Council"],"answer":2,"explanation":"Articles 243M(3) and 243ZC(2) protect the Darjeeling Gorkha Hill Council set up under a West Bengal law. Bodoland and Karbi Anglong are Sixth Schedule bodies, already outside Part IX.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-156","question":"Consider the following statements about the composition of panchayats under Article 243C: 1. A State may provide for representation of MPs and MLAs in intermediate and district panchayats. 2. All members of a panchayat, whether or not chosen by direct election, have the right to vote in its meetings. 3. The chairperson of a village panchayat must be elected indirectly by and from its elected members. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 243C(4) gives every member a vote, unlike the special-knowledge nominees in municipalities. How a village chairperson is chosen is left to State law; only intermediate and district chairpersons must be elected by and from the elected members.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-157","question":"In a State with a Legislative Council, the Legislative Assembly is in session but the Council is not. Can the Governor promulgate an ordinance?","options":["No, because the Assembly, to which ministers are responsible, is in session","Yes, because the bar applies only when both Houses are in session","Only with the prior consent of the Speaker","Only if the President has given instructions"],"answer":1,"explanation":"Article 213(1) allows an ordinance except when the Assembly, or in a bicameral State both Houses, are in session. If either House is not sitting, the power is available.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-158","question":"When a Governor’s five-year term ends and no successor has been appointed:","options":["he continues to hold office until his successor enters office","the Chief Justice of the High Court automatically becomes Governor","the office falls vacant and the Chief Minister acts as Governor","he must vacate office on the last day of the fifth year"],"answer":0,"explanation":"The proviso to Article 156(3) keeps the Governor in office until his successor enters upon it. Other temporary arrangements are made by the President under Article 160, not automatically.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-state-local-govt-159","question":"Under Article 163(3), which question cannot be inquired into by any court?","options":["Whether, and if so what, advice was tendered by ministers to the Governor","Whether an ordinance issued by the Governor was really needed","Whether the Governor’s recommendation for President’s rule had any material basis","Whether the Governor acted within the limits of the State’s executive power"],"answer":0,"explanation":"Article 163(3) shields only the advice given by ministers. Ordinances (Krishna Kumar Singh), President’s rule (Bommai) and the limits of executive power can all be examined by courts.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-160","question":"Consider the following statements about autonomous district councils under the Sixth Schedule: 1. They can make laws on inheritance of property, marriage and divorce, and social customs, subject to the Governor’s assent. 2. They can set up village councils or courts to try suits and cases between members of Scheduled Tribes. 3. The Governor can increase or decrease the area of an autonomous district or change its name. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct: paragraph 3 gives the councils law-making power on such matters, paragraph 4 lets them set up village courts, and paragraph 1 lets the Governor reorganise districts by notification.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-161","question":"Which of these is NOT provided for in Part IX or Part IXA of the Constitution?","options":["State Election Commission","State Finance Commission","District Planning Committee","District Rural Development Agency"],"answer":3,"explanation":"The District Rural Development Agency is an executive body set up to run rural development schemes. The other three are in Articles 243K, 243I and 243ZD.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"polity-state-local-govt-162","question":"Under the Government of India Act, 1919, local self-government in the provinces was:","options":["a reserved subject, administered by an executive councillor","a transferred subject, in charge of an Indian minister responsible to the provincial legislature","a central subject, administered by the Governor-General","an excluded subject, kept outside the legislature’s purview"],"answer":1,"explanation":"Under dyarchy, local self-government, education and public health were transferred subjects run by Indian ministers, while law and order and finance stayed reserved.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-163","question":"A bill other than a Money Bill originates in a State Legislative Council and is passed there, but the Legislative Assembly rejects it. What happens?","options":["The Governor summons a joint sitting of the two Houses","The Council can pass it again, and it is then deemed passed","The bill comes to an end","The Governor refers it to the President for decision"],"answer":2,"explanation":"States have no joint sitting. Article 197 lets the Council only delay Assembly bills; a Council bill rejected by the Assembly simply dies.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-164","question":"Which of these is NOT charged on the Consolidated Fund of the State?","options":["The emoluments and allowances of the Governor","The salaries and allowances of the Speaker and Deputy Speaker of the Assembly","The salaries and allowances of the judges of the High Court","The pensions of the judges of the High Court"],"answer":3,"explanation":"High Court judges’ salaries are charged on the State fund under Article 202(3), but their pensions are charged on the Consolidated Fund of India under Article 112(3)(d).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-165","question":"Which Article empowers the Governor to make rules for the more convenient transaction of the business of the State government and for allocating that business among ministers?","options":["Article 154","Article 163","Article 166","Article 167"],"answer":2,"explanation":"Article 166(3) covers the rules of business. Article 154 vests executive power in the Governor, 163 provides the Council of Ministers and 167 sets the Chief Minister’s duty to inform the Governor.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"polity-state-local-govt-166","question":"Under Article 243ZD, after a District Planning Committee consolidates the plans of the panchayats and municipalities into a draft development plan for the district, its chairperson forwards that plan to:","options":["the State government","the Union Ministry of Panchayati Raj","the Governor, for his assent","the State Finance Commission"],"answer":0,"explanation":"Article 243ZD(4) requires the chairperson to forward the draft plan to the State government; the Metropolitan Planning Committee’s plan likewise goes to the State government under Article 243ZE.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"polity-state-local-govt-167","question":"Who is empowered by Article 160 to make provision for the discharge of the functions of a Governor in a contingency not provided for in the Chapter on the Governor?","options":["The State Legislature, by law","Parliament, by law","The Chief Justice of the High Court","The President"],"answer":3,"explanation":"Article 160 lets the President make such provision as he thinks fit; in practice he gives a neighbouring Governor additional charge or asks the High Court Chief Justice to act.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-168","question":"Consider the following statements about the subordinate judiciary: 1. District judges are appointed by the Governor in consultation with the High Court. 2. An advocate can be directly appointed a district judge only if he has at least seven years' practice and is recommended by the High Court. 3. Appointments to the judicial service other than district judges are made by the Governor after consulting the State Public Service Commission and the High Court. 4. District judges are appointed by the Chief Justice of the High Court on the recommendation of the State Public Service Commission. How many of the above statements are correct?","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"Statements 1 and 2 restate Article 233 and statement 3 restates Article 234. Statement 4 is wrong: the Governor, not the Chief Justice, appoints district judges.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-169","question":"Under Article 243D(5), the reservation of panchayat seats for Scheduled Castes and Scheduled Tribes, and of chairpersons' offices for them, ceases to have effect:","options":["Ten years after the commencement of the 73rd Amendment, unless extended by the State","When the State Finance Commission so recommends","Never, since it is a permanent feature of Part IX","When SC/ST seat reservation in the Lok Sabha and Assemblies ends under Article 334"],"answer":3,"explanation":"Article 243D(5) ties the SC/ST reservation (but not the reservation for women) to the period in Article 334, which governs the reservation of seats in the Lok Sabha and State Assemblies.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-170","question":"Consider the following statements about the reach of Part IX: 1. The 83rd Amendment (2000) exempted Arunachal Pradesh from the reservation of panchayat seats for Scheduled Castes. 2. Part IX does not apply to Nagaland, Meghalaya and Mizoram. 3. Part IX applies in full to the hill areas of Manipur that have District Councils. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 243M(3A) gives 1 (Arunachal has a negligible SC population) and Article 243M(2)(a) gives 2. Article 243M(2)(b) keeps the hill areas of Manipur with District Councils outside Part IX, so 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-171","question":"Under Article 243ZE, what share of the members of a Metropolitan Planning Committee must be elected by and from the elected members of the municipalities and the chairpersons of the panchayats in the metropolitan area?","options":["At least four-fifths","At least two-thirds","At least one-half","At least three-fourths"],"answer":1,"explanation":"For a Metropolitan Planning Committee it is two-thirds, in proportion to the urban and rural populations. The four-fifths figure applies to District Planning Committees under Article 243ZD.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-172","question":"How many of the following matters are listed in the Twelfth Schedule (municipalities)? Fire services, Libraries, Regulation of slaughter houses and tanneries, Minor irrigation","options":["Only one","Only two","Only three","All four of them"],"answer":1,"explanation":"Fire services and regulation of slaughter houses and tanneries are Twelfth Schedule items. Libraries and minor irrigation are in the Eleventh Schedule (panchayats).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-173","question":"How many of the following matters are listed in the Eleventh Schedule (panchayats)? Public distribution system, Fire services, Fisheries, Cattle pounds and prevention of cruelty to animals","options":["Only one","Only two","Only three","All four of them"],"answer":1,"explanation":"The public distribution system and fisheries are Eleventh Schedule items. Fire services and cattle pounds belong to the Twelfth Schedule.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-174","question":"In the three-tier structure recommended by the Balwant Rai Mehta Committee (1957), which tier was to be the executive body, and which an advisory, coordinating and supervisory body chaired by the Collector?","options":["Zila Parishad executive; Gram Panchayat advisory","Gram Panchayat executive; Zila Parishad advisory","Zila Parishad executive; Panchayat Samiti advisory","Panchayat Samiti executive; Zila Parishad advisory"],"answer":3,"explanation":"Balwant Rai Mehta made the block-level Panchayat Samiti the executive body and the Zila Parishad, with the Collector as chairman, an advisory body. The Ashok Mehta Committee later made the Zila Parishad the executive tier.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-175","question":"How many of the following were recommendations of the Ashok Mehta Committee (1978)? 1. A two-tier system of Zila Parishad and Mandal Panchayat 2. The district as the first point of decentralisation under popular supervision below the State 3. Official participation of political parties in panchayat elections 4. The District Collector as chairman of the Zila Parishad","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"Statements 1–3 are Ashok Mehta recommendations. A Collector-chaired Zila Parishad was Balwant Rai Mehta's idea; Ashok Mehta made the Zila Parishad the executive body under popular control.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-176","question":"Which committee observed that the bureaucratisation of development administration had reduced Panchayati Raj institutions to ‘grass without roots’?","options":["L. M. Singhvi Committee","G. V. K. Rao Committee","Thungon Committee","Ashok Mehta Committee"],"answer":1,"explanation":"The G. V. K. Rao Committee (1985) used the phrase and proposed a District Development Commissioner to head district administration.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-177","question":"Match the committee with its recommendation: A. G. V. K. Rao (1985) B. L. M. Singhvi (1986) C. Thungon (1988) D. Gadgil (1988) — 1. Post of District Development Commissioner 2. Constitutional recognition, revitalised Gram Sabha and nyaya panchayats 3. District Collector as the chief executive officer of the Zila Parishad 4. The scheme that formed the basis of the 64th Amendment Bill, 1989","options":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-1, B-2, C-4, D-3","A-3, B-2, C-1, D-4"],"answer":0,"explanation":"Rao proposed a DDC, Singhvi constitutional status and nyaya panchayats, the Thungon sub-committee a Collector as the Zila Parishad's CEO, and the Gadgil committee the design taken up in the 64th Amendment Bill.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-178","question":"Consider the following statements about the Tribes Advisory Council under the Fifth Schedule: 1. It has not more than twenty members, about three-fourths of whom are Scheduled Tribe members of the State Legislative Assembly. 2. One may be set up even in a State with Scheduled Tribes but no Scheduled Areas, if the President so directs. 3. The Constitution makes the Governor its chairman. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Paragraph 4 of the Fifth Schedule supports 1 and 2 (Tamil Nadu and West Bengal have such Councils). The Constitution does not name the Governor as chairman; the chair is fixed by rules, usually the Chief Minister.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-179","question":"Which of the following States has Scheduled Areas declared under the Fifth Schedule?","options":["Arunachal Pradesh","West Bengal","Tamil Nadu","Himachal Pradesh"],"answer":3,"explanation":"Kinnaur, Lahaul and Spiti and parts of Chamba in Himachal Pradesh are Scheduled Areas. Kerala, Tamil Nadu and West Bengal have Scheduled Tribes but no Scheduled Areas.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-180","question":"Consider the following statements: 1. In Har Sharan Verma v. Tribhuvan Narain Singh (1971), the Supreme Court upheld the appointment of a non-member as Chief Minister. 2. In S. R. Chaudhuri (2001), it held that a non-member cannot be reappointed minister repeatedly without getting elected. 3. In B. R. Kapur v. State of Tamil Nadu (2001), it held that a person convicted and disqualified from contesting cannot be appointed Chief Minister under Article 164(4). How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"All three are correct: Article 164(4) allows a non-member for six months, but not as a device for repeated reappointment, and not for a person who is himself disqualified from membership.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-181","question":"Consider the following statements: 1. In Shivraj Singh Chouhan v. Speaker (2020), the Supreme Court held that a Governor may call for a floor test even while the Assembly is in session, if there is objective material that the government has lost its majority. 2. In Subhash Desai (2023), a Constitution Bench held that the Maharashtra Governor's call for a floor test in June 2022 was not justified. 3. In Subhash Desai, the Court restored the Uddhav Thackeray government to office. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The Court found the Governor's decision unjustified but could not restore the government because the Chief Minister had resigned without facing the floor test, so statement 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-182","question":"In Kishansing Tomar v. Municipal Corporation of Ahmedabad (2006), the Supreme Court held that:","options":["The State Government may postpone municipal elections until delimitation is finished","Municipal polls must finish before the five-year term ends, with the State aiding the SEC","A municipality's term may be extended by up to one year during a natural calamity","Municipal elections fall under the Election Commission of India when the State Commission is vacant"],"answer":1,"explanation":"The Court read Article 243U to require timely elections, with State Governments bound to help the State Election Commission; delimitation or other delays cannot justify postponing them.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-183","question":"In Vikas Kishanrao Gawali v. State of Maharashtra (2021), the Supreme Court laid down a ‘triple test’ for:","options":["Disqualifying a panchayat member for defection","Dissolving a municipality before its term ends","Postponing panchayat elections during an emergency","Reserving seats for backward classes in local bodies"],"answer":3,"explanation":"OBC reservation in local bodies needs a dedicated commission's empirical inquiry, local-body-wise proportions, and a cap so that total reservation for SCs, STs and OBCs does not exceed 50%.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-184","question":"In Rajbala v. State of Haryana (2015), the Supreme Court upheld a State law that, for panchayat candidates, prescribed:","options":["A bar on members of cooperative societies","A minimum educational qualification and a functional toilet at home","Residence in the village for ten years and ownership of land","A two-child norm and a minimum age of 25 years"],"answer":1,"explanation":"Rajbala upheld Haryana's 2015 amendment requiring minimum education, a functional toilet and no arrears of certain dues. The two-child norm had been upheld earlier, in Javed (2003).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-185","question":"Under the Gram Nyayalayas Act, 2008, a Gram Nyayalaya:","options":["Is a Nyaya Panchayat made compulsory in every State by the 73rd Amendment","Is set up in every village and is presided over by the elected Sarpanch","Works at intermediate panchayat level under a first-class judicial magistrate","Is presided over by a respected local person elected by the Gram Sabha"],"answer":2,"explanation":"The Nyayadhikari, a first-class magistrate appointed by the State in consultation with the High Court, heads a court for each intermediate panchayat or group of panchayats and may hold mobile sittings. Part IX does not provide for nyaya panchayats.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-186","question":"Consider the following statements about State Legislative Councils: 1. Tamil Nadu abolished its Council in 1986. 2. Andhra Pradesh abolished its Council in 1985 and revived it in 2007. 3. West Bengal and Punjab abolished their Councils around 1969–70. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"All three are correct; each change was made by an Act of Parliament under Article 169 after a resolution of the Assembly.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-187","question":"Consider the following statements about the Speaker of a State Legislative Assembly: 1. He can be removed by a resolution passed by a majority of all the then members of the Assembly. 2. At least fourteen days' notice is needed to move such a resolution. 3. On dissolution of the Assembly, he vacates office immediately. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 179 gives 1 and 2. Its proviso keeps the Speaker in office after dissolution until just before the first meeting of the new Assembly, so 3 is wrong.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-188","question":"Under Article 212, courts may not inquire into the validity of proceedings in a State legislature on the ground of:","options":["Any violation of the Constitution","Any breach of Fundamental Rights by a law passed","Any action taken without legislative competence","Any alleged irregularity of procedure"],"answer":3,"explanation":"Article 212 shields only procedural irregularity; courts can still examine illegality or unconstitutionality, as the Supreme Court held for the parallel Article 122 in Raja Ram Pal (2007).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-189","question":"Consider the following statements about Money Bills in a State legislature: 1. They can be introduced only in the Legislative Assembly. 2. They can be introduced only on the recommendation of the Governor. 3. The Legislative Council can hold up a Money Bill for at most three months. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Articles 198 and 207 give 1 and 2. The Council must return a Money Bill within 14 days, so 3 is wrong (three months applies to ordinary Bills).","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-190","question":"While a Proclamation of Emergency is in operation, the term of a State Legislative Assembly may be extended by:","options":["The Governor by order, one year at a time, ending when the Proclamation ceases","Parliament by law, one year at a time, ending at most six months after the Proclamation ceases","Parliament by law, six months at a time, ending at most one year after the Proclamation ceases","The Assembly itself by a two-thirds majority, for up to two years"],"answer":1,"explanation":"The proviso to Article 172(1) mirrors Article 83(2) for the Lok Sabha: Parliament may extend by law, not more than a year at a time and not beyond six months after the Emergency ends.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-191","question":"Consider the following statements about seats in State Legislative Assemblies under Article 170: 1. The total number of seats in each Assembly is frozen on the basis of the 1971 Census until the first Census after 2026. 2. The territorial constituencies within a State were readjusted on the basis of the 2001 Census. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"The proviso to Article 170(3) (84th and 87th Amendments) freezes the total seats on the 1971 Census while allowing constituency boundaries to be redrawn on the 2001 Census.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-192","question":"Consider the following statements: 1. Article 40 directs the State to organise village panchayats as units of self-government. 2. The 73rd Amendment requires every State to set up Nyaya Panchayats. 3. A Gram Sabha's powers are those that the State legislature gives it by law. Which of the above is/are correct?","options":["1 and 3 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 40 is a Directive Principle and Article 243A leaves the Gram Sabha's powers to State law. Nyaya Panchayats were recommended by committees but are not part of Part IX.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-193","question":"Which one of the following is NOT appointed by the Governor of a State?","options":["The Advocate General","The State Election Commissioner","A judge of the High Court","The Chairman of the State Public Service Commission"],"answer":2,"explanation":"High Court judges are appointed by the President under Article 217, with the Governor only consulted. The Governor appoints the Advocate General (165), the State Election Commissioner (243K) and PSC members (316).","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-194","question":"Consider the following statements about Autonomous District Councils under the Sixth Schedule: 1. Laws made by a District Council on matters such as land, forests other than reserved forests and inheritance need the Governor's assent. 2. A District Council may assess and collect land revenue and levy certain taxes. 3. Acts of Parliament apply to autonomous districts in all cases, with no power to exclude or modify them. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Paragraphs 3, 8 and 12 of the Sixth Schedule support 1 and 2. Paragraph 12 lets the Governor (or the President, in some States) direct that an Act of Parliament shall not apply, or apply with modifications, so 3 is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-195","question":"In State of Punjab v. Principal Secretary to the Governor of Punjab (2023), the Supreme Court held that when a Governor decides to withhold assent to a Bill under Article 200, he:","options":["Must reserve the Bill for the President, who alone can finally refuse assent","May withhold only if the Advocate General advises that the Bill is unconstitutional","Must send it back to the legislature under the first proviso; he cannot sit on it","May withhold assent finally, and the Bill then lapses without going back to the legislature"],"answer":2,"explanation":"The Court read ‘withhold’ together with the first proviso: the Governor must send the Bill back, and if the legislature passes it again he cannot withhold assent. Otherwise an unelected Governor could veto Bills at will.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-196","question":"A State Legislative Assembly has 90 members. Under Article 164(1A), what is the largest number of ministers, including the Chief Minister, that the State can have?","options":["13","14","12","15"],"answer":0,"explanation":"15% of 90 is 13.5, and the number may not exceed 15%, so the cap is 13. The minimum of 12 does not bind here, and rounding 13.5 up to 14 would breach the limit.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-197","question":"Under Article 239AA(4), the Council of Ministers of the National Capital Territory of Delhi may not exceed what share of the total membership of its Legislative Assembly?","options":["Fifteen per cent","Twenty per cent","Twelve members or 15%, whichever is more","Ten per cent"],"answer":3,"explanation":"Article 239AA(4) caps Delhi's Council of Ministers at 10% of the Assembly (seven for 70 members). The 15% cap with a floor of 12 applies to States under Article 164(1A).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-198","question":"The Governor nominates members of a State Legislative Council from persons with special knowledge or practical experience in literature, science, art, social service and one more field that is NOT listed for presidential nominations to the Rajya Sabha. Which field is it?","options":["Sports and games","Co-operative movement","Law and jurisprudence","Education and training"],"answer":1,"explanation":"Article 171(5) adds ‘co-operative movement’ to the four fields of Article 80(3). Sports, law and education appear in neither list.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-199","question":"A State Legislative Council has 96 members, constituted in the proportions laid down in Article 171(3). How many of them are nominated by the Governor?","options":["16","12","8","32"],"answer":0,"explanation":"One-third (32) are elected by local authorities, one-twelfth (8) by graduates, one-twelfth (8) by teachers and one-third (32) by MLAs; the remainder, 96 − 80 = 16 (one-sixth), are nominated.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-200","question":"How many of the following are compulsory for every State to which Part IX applies? 1. Indirect election of the chairperson of the district-level panchayat 2. A particular mode of electing the chairperson of the village panchayat 3. Representation of MPs and MLAs in panchayats 4. Constituting a Finance Commission every five years","options":["Only one","Only two","Only three","All four of them"],"answer":1,"explanation":"Article 243C(5)(b) makes intermediate and district chairpersons indirectly elected, and Article 243I makes the Finance Commission compulsory. The village chairperson's mode of election and the representation of legislators are left to State law.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-201","question":"Under Part IXA, the manner of electing the chairperson of a municipality (such as a Mayor) is:","options":["Direct election by voters, as fixed by Article 243R","Indirect election by councillors, as fixed by Article 243R","Left to be decided by the State legislature by law","Nomination by the Governor on the advice of the State Election Commission"],"answer":2,"explanation":"Article 243R(2)(b) leaves the manner of electing chairpersons to State law, which is why some States elect Mayors directly and others through councillors.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-202","question":"Under paragraph 1 of the Sixth Schedule, who may, by public notification, create a new autonomous district or alter the area or name of an existing one?","options":["The President","Parliament, by law","The State legislature, by a two-thirds majority","The Governor"],"answer":3,"explanation":"The Governor has this power, though changes such as creating or altering districts need the report of a commission appointed under paragraph 14.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-203","question":"Consider the following statements: 1. The Bodoland Territorial Council functions under the Sixth Schedule. 2. The Gorkhaland Territorial Administration functions under the Sixth Schedule. 3. The Ladakh Autonomous Hill Development Councils were created by statute, not under the Sixth Schedule. Which of the above is/are correct?","options":["1 and 3 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The Bodoland council was brought under the Sixth Schedule in 2003. The GTA was set up under a West Bengal Act of 2011 and the Ladakh councils under a 1995 Act, so statement 2 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-204","question":"The Sikkim Legislative Assembly, under special provisions linked to Article 371F, includes a seat reserved for the:","options":["Retired soldiers of the State","Sangha, the Buddhist monasteries","Lepcha tribe alone","Nepali-speaking plainsmen"],"answer":1,"explanation":"One seat is reserved for the Sangha, elected by the monasteries, to protect the interests of the Buddhist community; Article 371F(f) allows Parliament to provide for such representation.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-205","question":"Consider the following statements: 1. The Puducherry Legislative Assembly includes members nominated by the Central Government. 2. The Delhi Legislative Assembly includes members nominated by the Lieutenant Governor. 3. Parliament can override a law made by the Puducherry Assembly. Which of the above is/are correct?","options":["1 and 3 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Puducherry's Assembly has up to three members nominated by the Centre under the 1963 Act, and its laws remain subject to Parliament's. Delhi's 70-member Assembly is wholly elected, so statement 2 is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-206","question":"Who administers the Union territory of Chandigarh?","options":["The Lieutenant Governor of Delhi, as Administrator","The Chief Minister of Punjab and Haryana jointly","The Governor of Punjab, as Administrator","An elected Mayor with powers of a State Government"],"answer":2,"explanation":"Since 1984, the Governor of Punjab has also served as Administrator of Chandigarh, an arrangement made under Article 239.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-207","question":"A Governor serves as Chancellor of most State universities. This role is derived from:","options":["The Seventh Schedule's Union List","The oath taken by the Governor under Article 159","Article 163 of the Constitution","The State laws establishing those universities"],"answer":3,"explanation":"The chancellorship is conferred by each university's Act passed by the State legislature, not by the Constitution, which is why States such as Kerala and Tamil Nadu have sought to change it by law.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-208","question":"The Balwant Rai Mehta Committee was set up in 1957 mainly to examine the working of:","options":["The Zamindari Abolition Acts passed by the States","The Community Development Programme and National Extension Service","The Five-Year Plans in the industrial sector","The elected municipal bodies created under the Montford reforms of 1919"],"answer":1,"explanation":"The Community Development Programme (1952) and National Extension Service (1953) had failed to draw in people, so the committee recommended ‘democratic decentralisation’ through Panchayati Raj.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-209","question":"Consider the following statements about State finance: 1. The Contingency Fund of a State is placed at the disposal of the Governor. 2. No demand for a grant can be made in the Assembly except on the Governor's recommendation. 3. The emoluments and allowances of the Governor are charged on the Consolidated Fund of the State. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Articles 267(2), 203(3) and 202(3)(a) respectively.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-210","question":"In D. C. Wadhwa v. State of Bihar (1987), the Supreme Court held that the Governor's practice of re-promulgating ordinances again and again without placing them before the legislature was:","options":["A valid exercise of Article 213, if each ordinance was laid in time","Valid, since the Governor's satisfaction is beyond judicial review","A fraud on the Constitution","Invalid only for ordinances on money matters"],"answer":2,"explanation":"Bihar had kept ordinances alive for years by re-promulgation; the Court called this a subversion of the democratic process. Krishna Kumar Singh (2017) later reaffirmed the point.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-211","question":"In Keisham Meghachandra Singh v. Speaker, Manipur Legislative Assembly (2020), the Supreme Court:","options":["Held that the Governor, not the Speaker, decides disqualification under the Tenth Schedule","Struck down paragraph 6 of the Tenth Schedule as violating the basic structure","Held that a Speaker's decision on disqualification is wholly beyond judicial review","Set a three-month norm for Speakers to decide disqualification pleas and suggested a tribunal"],"answer":3,"explanation":"The Court criticised delays by Speakers, set a three-month norm and suggested a permanent tribunal; it did not disturb the Speaker's role, which Kihoto Hollohan had upheld subject to judicial review.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-212","question":"A panchayat has 25 seats filled by direct election. Scheduled Castes form 20% of its population and there are no Scheduled Tribes. Under Article 243D, what are the minimum numbers of seats reserved for women in all, and for SC women within the SC seats?","options":["9 and 2","8 and 1","9 and 1","8 and 2"],"answer":0,"explanation":"SC seats are 20% of 25 = 5. ‘Not less than one-third’ of 5 is at least 1.67, so 2 SC women; ‘not less than one-third’ of 25 is at least 8.33, so 9 women in all (the 2 included). Rounding down gives the trap answers.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-213","question":"Assertion (A): Every municipality must have Wards Committees. Reason (R): Article 243S requires Wards Committees only in municipalities with a population of three lakh or more.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R is the correct rule, and it is exactly why A is false: smaller municipalities need not have Wards Committees.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-214","question":"Assertion (A): Sikkim, with a 32-member Assembly, may have a Council of Ministers of 12. Reason (R): Fifteen per cent of 32 is less than twelve.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but A follows from the proviso to Article 164(1A), which says the number of ministers shall not be less than twelve; the arithmetic in R only shows why that floor matters for small States.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-215","question":"Under the Scheduled Tribes and Other Traditional Forest Dwellers (Recognition of Forest Rights) Act, 2006, which body initiates the process of determining individual and community forest rights?","options":["The State Forest Department","The Gram Sabha","The Tribes Advisory Council","The District Collector"],"answer":1,"explanation":"The Gram Sabha receives and verifies claims and passes resolutions, which then go to sub-divisional and district-level committees.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-216","question":"Under Article 243ZD, who chairs a District Planning Committee?","options":["The chairperson of the district panchayat, as fixed by the Constitution","The District Collector, as fixed by the Constitution","Whoever the State law names, since the Constitution leaves it to the State","The Minister in charge of the district, as fixed by the Constitution"],"answer":2,"explanation":"Article 243ZD(2) leaves the composition and the manner of choosing chairpersons to State law; States variously choose a minister, the Zila Parishad chairperson or another person.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-217","question":"A State with a 120-member Legislative Assembly decides to create a Legislative Council. Under Article 171(1), its Council must have:","options":["Between 40 and 60 members","At most 40 members, with no minimum","Between 30 and 40 members","Exactly 40 members"],"answer":3,"explanation":"The Council may not exceed one-third of the Assembly (40) and may not be smaller than 40, so for a 120-member Assembly both limits meet at exactly 40.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-218","question":"In Government of NCT of Delhi v. Union of India (2018), a Constitution Bench held that the Lieutenant Governor:","options":["Is bound by ministerial advice even on police, public order and land","Is ordinarily bound by ministerial advice on matters within the Assembly's domain","Has the same discretion as a State Governor under Article 163","Can veto any decision of the Delhi Council of Ministers at his discretion"],"answer":1,"explanation":"The Court held that the LG must ordinarily act on aid and advice and may refer a difference to the President only in exceptional cases, not on every matter; police, public order and land remain outside the Assembly's domain.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-219","question":"Consider the following statements: 1. The Finance Commission constituted under Article 243I also reviews the finances of municipalities. 2. The Central Finance Commission recommends measures to augment a State's Consolidated Fund to supplement the resources of panchayats and municipalities. 3. The recommendations of a State Finance Commission are binding on the State Government. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 243Y uses the same Commission for municipalities and Article 280(3)(bb) and (c) give 2. SFC recommendations are only laid before the legislature with an explanatory memorandum of action taken; they are not binding.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-220","question":"For the purposes of Part IX, a ‘village’ under Article 243(g) means:","options":["A revenue village as recorded in the latest Census","Any settlement whose population is below five thousand in the last Census","A village or group of villages specified by the Governor by public notification","A village so notified by the State Election Commission before each election"],"answer":2,"explanation":"Article 243(g) leaves the unit to the Governor's notification, which may combine villages; it is not tied to the Census or a population figure.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-221","question":"Consider the following statements: 1. The same State Election Commission conducts both panchayat and municipal elections. 2. Subject to the Constitution, the State legislature may make provisions for panchayat elections. 3. The State Election Commission works under the superintendence of the Election Commission of India. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 243ZA uses the Commission of Article 243K for municipalities, and Article 243K(4) lets the State legislature legislate on panchayat elections. The SEC is independent of the ECI, so 3 is wrong.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-state-local-govt-222","question":"In 2022, Parliament amended the Delhi Municipal Corporation Act, 1957 to:","options":["Give the Delhi Government full control over municipal staff","Make the Mayor of Delhi directly elected for five years","Transfer municipal elections in Delhi to the Election Commission of India","Unify the three municipal corporations of Delhi into a single corporation"],"answer":3,"explanation":"The 2022 amendment merged the North, South and East Delhi corporations, which had been split in 2011–12, into one Municipal Corporation of Delhi.","difficulty":"hard","source":"UPSC Prelims"},
];

export default questions;
